// The physics library (Jolt behind a C interface, code_physics), which is loaded when it is first needed, from the directory of the
// program, like the libraries of FFmpeg. Nothing needs it to run: without it the picks and collisions are done by the runtime itself.
#pragma once

#include "blitzphysics.h"

namespace bb::physics {
	struct api {
		decltype(&::bp_world_create)           world_create;
		decltype(&::bp_world_destroy)          world_destroy;
		decltype(&::bp_mesh_create)            mesh_create;
		decltype(&::bp_mesh_destroy)           mesh_destroy;
		decltype(&::bp_body_add_mesh)          body_add_mesh;
		decltype(&::bp_body_remove)            body_remove;
		decltype(&::bp_body_set_transform)     body_set_transform;
		decltype(&::bp_world_update)           world_update;
		decltype(&::bp_cast_closest)           cast_closest;
		decltype(&::bp_cast_closest_batch)     cast_closest_batch;
	};

	// The library, or null if it is not next to the program or is not the version that the runtime is made for. Looked for once.
	api const* library();
} // namespace bb::physics
